--
-- Name: subscriptions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.subscriptions (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    created_by character varying(255) NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL,
    updated_by character varying(255) NOT NULL,
    version integer,
    billing_cycle character varying(20) NOT NULL,
    end_date date NOT NULL,
    notes character varying(255),
    plan character varying(20) NOT NULL,
    price numeric(10,2),
    start_date date NOT NULL,
    status character varying(20) NOT NULL,
    tenant_id bigint NOT NULL,
    CONSTRAINT subscriptions_billing_cycle_check CHECK (((billing_cycle)::text = ANY ((ARRAY['MONTHLY'::character varying, 'YEARLY'::character varying])::text[]))),
    CONSTRAINT subscriptions_plan_check CHECK (((plan)::text = ANY ((ARRAY['FREE'::character varying, 'STANDARD'::character varying, 'PREMIUM'::character varying])::text[]))),
    CONSTRAINT subscriptions_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'EXPIRED'::character varying, 'CANCELLED'::character varying])::text[])))
);


ALTER TABLE public.subscriptions OWNER TO postgres;

--
-- Name: suivi_heures_enseignant; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.suivi_heures_enseignant (
    id bigint NOT NULL,
    tenant_id character varying(255) NOT NULL,
    enseignant_id bigint NOT NULL,
    numero_semaine integer NOT NULL,
    annee_academique character varying(20) NOT NULL,
    heures_prevues double precision NOT NULL,
    heures_realisees double precision NOT NULL,
    heures_manquees double precision NOT NULL,
    taux_presence double precision NOT NULL,
    notes text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    created_by character varying(255) DEFAULT 'system'::character varying NOT NULL,
    updated_by character varying(255) DEFAULT 'system'::character varying NOT NULL,
    version integer DEFAULT 0
);


ALTER TABLE public.suivi_heures_enseignant OWNER TO postgres;

